"""Behavior tests: recover random cameras, reject inconsistent drawings."""
import math
import random
import unittest
from camera import calibrate, project


def annotations(a, e):
    # Independent analytic vectors (not generated by project()).
    a, e = math.radians(a), math.radians(e)
    vectors = {'x': (-math.sin(a), math.sin(e)*math.cos(a)),
               'y': (math.cos(a), math.sin(e)*math.sin(a)), 'z': (0, -math.cos(e))}
    return {k+'_edges': [[[20+i*30, 50+i*10],
                         [20+i*30+200*v[0], 50+i*10+200*v[1]]]
                        for i in range(3)] for k, v in vectors.items()}


class CameraTests(unittest.TestCase):
    def test_random_recovery(self):
        rng = random.Random(41)
        for _ in range(100):
            a, e = rng.uniform(10, 80), rng.uniform(15, 70)
            result = calibrate(annotations(a, e))
            self.assertEqual(result['status'], 'candidate')
            self.assertAlmostEqual(result['azimuth_deg'], a, places=8)
            self.assertAlmostEqual(result['elevation_deg'], e, places=8)

    def test_isometric(self):
        r = calibrate(annotations(45, math.degrees(math.asin(1/math.sqrt(3)))))
        self.assertAlmostEqual(r['elevation_deg'], 35.26438968, places=7)

    def test_two_to_one_is_not_true_iso(self):
        r = calibrate(annotations(45, math.degrees(math.asin(.5))))
        self.assertAlmostEqual(r['elevation_deg'], 30)

    def test_bad_parallelism(self):
        data = annotations(45, 30)
        data['x_edges'][1][1][1] += 35
        self.assertEqual(calibrate(data)['status'], 'reject')

    def test_roll(self):
        data = annotations(45, 30)
        for edge in data['z_edges']:
            edge[1][0] += 20
        self.assertEqual(calibrate(data)['status'], 'reject')

    def test_impossible_ground_axes(self):
        data = annotations(45, 30)
        data['y_edges'] = data['x_edges']
        self.assertEqual(calibrate(data)['status'], 'reject')

    def test_short_or_missing(self):
        with self.assertRaises(ValueError):
            calibrate({'x_edges': []})
        data = annotations(45, 30)
        data['x_edges'][0] = [[0, 0], [1, 1]]
        with self.assertRaises(ValueError):
            calibrate(data)

    def test_rotations_and_scale(self):
        a, e = 37, 29
        for yaw, component in ((a, 0), (a+90, 1)):
            p = (math.cos(math.radians(yaw)), math.sin(math.radians(yaw)), 0)
            self.assertAlmostEqual(project(p, a, e)[component], 0, places=10)
        data = annotations(a, e)
        data['scale_reference'] = {'edge': [[0, 0], [0, 3*42*math.cos(math.radians(e))]], 'world_length': 3}
        self.assertAlmostEqual(calibrate(data)['pixels_per_world_unit'], 42)


if __name__ == '__main__':
    unittest.main()
